use strict;
use warnings;
use feature 'say';

my $item = 'chapter';
my $pages = 18;
my $total = $pages + 2;
say "$item: $total pages";

use strict;
use warnings;
use feature 'say';

my @items = ('tea', 'coffee', 'tea');
my %counts;
for my $item (@items) {
    $counts{$item} = ($counts{$item} // 0) + 1;
}
for my $key (sort keys %counts) {
    say "$key: $counts{$key}";
}

use strict;
use warnings;
use feature 'say';

for my $line ('PASS 12', 'partial PASS 12', 'FAIL 3') {
    if ($line =~ /\A([A-Z]+) ([0-9]+)\z/) {
        my ($label, $count) = ($1, $2);
        say "$label: $count";
    } else {
        say "skipped";
    }
}

use strict;
use warnings;
use feature 'say';

sub average {
    return undef if !@_;
    my $total = 0;
    $total += $_ for @_;
    return $total / @_;
}

my $mean = average(2, 4, 6);
my $empty = average();
say $mean // 'no values';
say $empty // 'no values';

use strict;
use warnings;
use feature 'say';

my $text = "tea\n\ncoffee\n";
open my $input, '<', \$text or die "open input: $!";
while (my $line = <$input>) {
    chomp $line;
    next unless length $line;
    say "item: $line";
}
close $input or die "close input: $!";
